-- Account setup tokens no longer point at a pre-existing student.
-- DropForeignKey
ALTER TABLE "account_setup_tokens" DROP CONSTRAINT "account_setup_tokens_membership_id_fkey";

-- DropIndex
DROP INDEX "account_setup_tokens_membership_id_idx";

-- AlterTable
ALTER TABLE "account_setup_tokens" DROP COLUMN "membership_id";

-- Membership IDs are now generated by the database, starting at 4 digits.
-- CreateSequence
CREATE SEQUENCE "students_membership_id_seq" START WITH 1000 INCREMENT BY 1 OWNED BY "students"."membership_id";

-- AlterTable
ALTER TABLE "students" ALTER COLUMN "membership_id" SET DEFAULT nextval('"students_membership_id_seq"');
